/* Badlands Field Map service worker (generated by tools/postbuild.mjs).
 * - App shell and landmark data: precached per version, served cache-first.
 * - Map tiles: served from the "bfm-tiles-v1" cache when downloaded, otherwise from the network.
 * - Personal records live in IndexedDB and are never touched here.
 */
const VERSION = 'a5c74cc7b5ac';
const APP_CACHE = `bfm-app-${VERSION}`;
const TILE_CACHE = 'bfm-tiles-v1';
const PRECACHE = ["./","./assets/index-BiDNl0Ea.js","./assets/index-DD26Aqxe.css","./data/index.json","./data/nasdara-core.json","./icons/apple-touch-icon.png","./icons/favicon-64.png","./icons/icon-192.png","./icons/icon-512.png","./icons/icon-maskable-512.png","./manifest.webmanifest"];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(APP_CACHE);
      // Fetch each file fresh so a half-updated HTTP cache cannot mix versions.
      await Promise.all(
        PRECACHE.map(async (url) => {
          const res = await fetch(new Request(url, { cache: 'reload' }));
          if (!res.ok) throw new Error(`precache failed: ${url} ${res.status}`);
          await cache.put(url, res);
        }),
      );
      // The first install activates at once; later versions wait for the user (see SKIP_WAITING).
      if (!self.registration.active) await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) if (key.startsWith('bfm-app-') && key !== APP_CACHE) await caches.delete(key);
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    event.respondWith(
      (async () => {
        const cache = await caches.open(APP_CACHE);
        return (await cache.match('./')) || (await cache.match('./index.html')) || fetch(req);
      })(),
    );
    return;
  }

  if (url.pathname.includes('/data/tiles/')) {
    event.respondWith(
      (async () => {
        const hit = await (await caches.open(TILE_CACHE)).match(req.url);
        if (hit) return hit;
        try {
          return await fetch(req);
        } catch {
          return new Response('', { status: 504, statusText: 'Tile not downloaded for offline use' });
        }
      })(),
    );
    return;
  }

  event.respondWith(
    (async () => {
      const cache = await caches.open(APP_CACHE);
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      try {
        return await fetch(req);
      } catch {
        return new Response('', { status: 504, statusText: 'Offline' });
      }
    })(),
  );
});
